#!/usr/bin/env python3
"""Build two removable home-screen shortcuts for the verified TOLF command names."""
import base64,plistlib,uuid,argparse
from pathlib import Path
ICONS={"on":"","off":""}
def build():
    payloads=[]
    for mode,label in [('on','VPN ВКЛ'),('off','VPN ВЫКЛ')]:
        ident='is.tolf.vpn.launcher.'+mode
        payloads.append({
          'PayloadType':'com.apple.webClip.managed','PayloadVersion':1,
          'PayloadIdentifier':ident,'PayloadUUID':str(uuid.uuid5(uuid.NAMESPACE_DNS,ident)).upper(),
          'PayloadDisplayName':label,'Label':label,
          'URL':'shortcuts://run-shortcut?name=TOLF-'+mode.upper(),
          'Icon':base64.b64decode(ICONS[mode]),'IsRemovable':True,
          'FullScreen':False,'Precomposed':True})
    return {'PayloadType':'Configuration','PayloadVersion':1,
      'PayloadIdentifier':'is.tolf.vpn.launchers','PayloadUUID':str(uuid.uuid5(uuid.NAMESPACE_DNS,'is.tolf.vpn.launchers')).upper(),
      'PayloadDisplayName':'TOLF — кнопки VPN','PayloadOrganization':'TOLF',
      'PayloadDescription':'Добавляет значки VPN ВКЛ и VPN ВЫКЛ для запуска установленных команд TOLF-ON и TOLF-OFF.',
      'PayloadRemovalDisallowed':False,'PayloadContent':payloads}
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('output',type=Path);a=p.parse_args()
    a.output.write_bytes(plistlib.dumps(build(),fmt=plistlib.FMT_XML,sort_keys=False))
    print('Created two WebClip payloads:',a.output)
